758	fn can_be_targeted(state: &GameState, target_id: ObjectId, caster: PlayerId, registry: &CardRegistry) -> bool {
759	    if state.has_keyword(target_id, Keyword::Hexproof, registry) {
760	        let controller = state.get_object(target_id)
761	            .map(|o| o.controller)
762	            .unwrap_or(PlayerId(255));
763	        if controller != caster {
764	            return false; // hexproof: can't be targeted by opponents
765	        }
766	    }
767	    true
